/* Original numeral stimuli and supplementary, nonstandard animal stimuli. */
window.ColorPlates = (() => {
  // Numeric artwork is baked from the project's historical ColorPlateArt.dots.
  // Each disk is a sequence of Float64 x, y, radius and three RGB bytes (little endian).
  const numericArtwork = {
  "demo": "",
  "p1": "",
  "d1": "",
  "p2": "",
  "d2": "",
  "p3": "",
  "d3": "",
  "p4": "",
  "d4": ""
};
  const numericDefinitions = [["demo","12","DEMO",0,["12","72","17","看不出"]],["p1","8","PROTAN",0.3,["8","6","3","看不出"]],["d1","3","DEUTAN",0.3,["3","5","8","看不出"]],["p2","29","PROTAN",0.22,["70","29","26","看不出"]],["d2","15","DEUTAN",0.22,["17","13","15","看不出"]],["p3","5","PROTAN",0.16,["6","2","5","看不出"]],["d3","6","DEUTAN",0.16,["8","5","6","看不出"]],["p4","74","PROTAN",0.11,["71","74","21","看不出"]],["d4","45","DEUTAN",0.11,["46","45","13","看不出"]]];
  const numeric = numericDefinitions.map(([id,answer,type,contrast,choices]) =>
    ({ id, kind:'number', answer, type, contrast, choices }));
  const [example, ...numbers] = numeric;

  // All silhouettes live on a 200 × 200 plane. They classify dot centres only;
  // neither the silhouette, a border nor the animal's name is painted onto a plate.
  const animals = [
    {
      id:'fish', answer:'小鱼', geometry:'p1', palette:'coral',
      choices:['小鸟','小鱼','兔子','看不出'],
      silhouette:'M55 92Q66 76 86 68Q95 52 115 48L111 63Q145 62 171 98Q153 129 120 137Q118 147 105 154L101 139Q74 139 55 114Q42 127 24 135L30 107L24 70Q40 75 55 92Z M145 85a5 5 0 1 0 .01 0Z'
    },
    {
      id:'rabbit', answer:'兔子', geometry:'d1', palette:'sage',
      choices:['小鱼','蝴蝶','兔子','看不出'],
      silhouette:'M143 73Q158 76 156 90Q162 99 163 103Q157 115 141 113L128 118Q128 136 138 143Q154 143 156 152Q151 157 132 156L110 154Q84 161 61 153Q48 154 45 144Q34 145 31 135Q29 124 39 120Q45 116 50 120Q51 97 69 87Q83 79 103 86Q107 78 119 73Q104 55 105 33Q105 24 111 27Q126 38 132 65Q130 44 140 27Q148 15 151 27Q154 44 143 73Z M144 86a4 4 0 1 0 .01 0Z'
    },
    {
      id:'butterfly', answer:'蝴蝶', geometry:'p3', palette:'berry',
      choices:['蝴蝶','兔子','小鸟','看不出'],
      silhouette:'M96 79Q81 56 57 44Q37 33 25 42Q20 65 35 85Q43 98 64 105Q40 107 44 128Q49 149 67 151Q82 148 96 121L97 139Q100 150 103 139L104 121Q118 148 133 151Q151 149 156 128Q160 107 136 105Q157 98 165 85Q180 65 175 42Q163 33 143 44Q119 56 104 79Q106 65 116 53L112 50Q102 59 100 70Q98 59 88 50L84 53Q94 65 96 79Z'
    },
    {
      id:'bird', answer:'小鸟', geometry:'d3', palette:'moss',
      choices:['兔子','小鸟','蝴蝶','看不出'],
      silhouette:'M37 107Q57 115 74 102Q86 90 95 70Q103 49 121 46Q145 41 151 64L170 69L150 78Q149 108 132 123Q122 132 107 135L111 151H121V157H105L100 136H92L88 151H96V157H79L84 135Q68 131 56 122L26 127L37 114L23 103Z M134 60a4 4 0 1 0 .01 0Z'
    }
  ].map(plate => ({ ...plate, kind:'animal' }));
  const questions = [];
  animals.forEach((animal,i) => questions.push(numbers[i*2],numbers[i*2+1],animal));

  const geometries = new Map();
  const animalDots = new Map();
  function numericDots(id) {
    if (geometries.has(id)) return geometries.get(id);
    const binary = atob(numericArtwork[id]);
    const bytes = Uint8Array.from(binary, ch => ch.charCodeAt(0));
    const view = new DataView(bytes.buffer);
    const dots = [];
    for (let start=0; start<bytes.length; start+=27) {
      const rgb = bytes[start+24]*65536 + bytes[start+25]*256 + bytes[start+26];
      dots.push({ x:view.getFloat64(start,true), y:view.getFloat64(start+8,true),
        r:view.getFloat64(start+16,true), color:'#'+rgb.toString(16).padStart(6,'0') });
    }
    geometries.set(id,dots);
    return dots;
  }

  // CIELAB pairs share the same lightness ladder; hue carries the outline.
  const palettes = {
    coral: [[-19,27],[39,28]],
    sage: [[32,21],[-27,27]],
    berry: [[-20,23],[36,9]],
    moss: [[33,16],[-24,31]]
  };
  function colorFromLab(lightness, a, b) {
    const fy = (lightness+16)/116;
    const x = 0.95047 * (fy+a/500)**3;
    const y = fy**3;
    const z = 1.08883 * (fy-b/200)**3;
    const srgb = v => {
      const linear = Math.min(1,Math.max(0,v));
      return Math.round(255*(linear<=0.0031308 ? 12.92*linear : 1.055*linear**(1/2.4)-0.055));
    };
    return 'rgb('+[
      srgb(3.2404542*x-1.5371385*y-0.4985314*z),
      srgb(-0.969266*x+1.8760108*y+0.041556*z),
      srgb(0.0556434*x-0.2040259*y+1.0572252*z)
    ].join(',')+')';
  }
  function animalArtwork(plate) {
    if (animalDots.has(plate.id)) return animalDots.get(plate.id);
    const lightness = [50,55,59,63,67,71,74];
    const colors = palettes[plate.palette].map(([a,b]) => lightness.map(l=>colorFromLab(l,a,b)));
    const region = new Path2D(plate.silhouette);
    const mask = document.createElement('canvas').getContext('2d');
    let seed = 4001+plate.id.charCodeAt(0);
    const dots = numericDots(plate.geometry).map(({x,y,r}) => {
      const inside = mask.isPointInPath(region,100+100*x,100+100*y,'evenodd');
      seed = (Math.imul(1664525,seed)+1013904223)>>>0;
      const tone = Math.floor(seed/4294967296*lightness.length);
      return { x,y,r, color:colors[inside?1:0][tone] };
    });
    animalDots.set(plate.id,dots);
    return dots;
  }
  function draw(canvas,plate) {
    const dots = plate.kind==='animal' ? animalArtwork(plate) : numericDots(plate.id);
    const size = 600;
    canvas.width = canvas.height = size;
    const ctx = canvas.getContext('2d');
    ctx.save();
    ctx.translate(size/2,size/2);
    ctx.scale(size/2,size/2);
    ctx.beginPath();
    ctx.arc(0,0,1,0,2*Math.PI);
    ctx.fillStyle = '#e7e2d2';
    ctx.fill();
    for (const dot of dots) {
      ctx.fillStyle = dot.color;
      ctx.beginPath();
      ctx.arc(dot.x,dot.y,dot.r,0,2*Math.PI);
      ctx.fill();
    }
    ctx.restore();
  }
  return { example,numbers,animals,questions,draw };
})();
